30	/**
31	 * Minimal, always-succeeding fake of `IWebGL2Context` — no real GPU exists
32	 * in this package's Node test environment. Compiles/links "succeed"
33	 * unconditionally so tests exercise the backend's call sequence, not a
34	 * real GLSL compiler.
35	 */
36	export class FakeWebGL2Context implements IWebGL2Context {
37	  readonly VERTEX_SHADER = 35633;
38	  readonly FRAGMENT_SHADER = 35632;
39	  readonly COMPILE_STATUS = 35713;
40	  readonly LINK_STATUS = 35714;
