26	    const layer = this.requireLayer();
27	    this.previousValue = getLayerPropertyValue(layer, this.propertyKey);
28	    setLayerPropertyValue(layer, this.propertyKey, this.value);
29	  }
30	
31	  undo(): void {
32	    setLayerPropertyValue(this.requireLayer(), this.propertyKey, this.previousValue);
33	  }
34	
35	  redo(): void {
36	    setLayerPropertyValue(this.requireLayer(), this.propertyKey, this.value);
37	  }
38	
39	  private requireLayer() {
40	    const layer = this.engine.registry.get(this.layerId);
41	    if (!layer) {
42	      throw new Error(`UpdateLayerCommand: unknown layer: "${this.layerId}"`);
43	    }
44	    return layer;
45	  }
46	}
