import { LayerEngine } from "@motion-studio/layer";
import { TimelineEngine, createComposition, createTrack } from "@motion-studio/timeline";
import { HistoryEngine } from "@motion-studio/history";
import {
  AssetCatalog,
  AssetManager,
  type IAssetCatalogEntry,
