    dragStateRef.current = {
      mode: "move",
      layerId: hit.layerId,
      startTransform: { ...hit.transform },
      startPointerCanvas: point,
    };
  }

  select({ layerIds: hit ? [hit.layerId] : [], trackItemIds: [] });
